#!/usr/bin/env python3
"""Generate the admitted GEMDOS source interface and target layout probe."""
import argparse
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
ABI=json.loads((ROOT/'abi/gemdos-compat.json').read_text())


def expected_layout():
    return [('XATTR bytes',ABI['xattr']['bytes'])]+[
        ('XATTR '+name,offset) for name,kind,offset in ABI['xattr']['fields']]+[
        ('WORD bytes',2),('LONG bytes',4),('pointer bytes',4)]


def files():
    header=['/* SPDX-License-Identifier: MIT',
        ' * Generated by tools/generate_gemdos_compat.py; do not edit. */',
        '#ifndef EXEC816_COMPAT_GEMDOS_H','#define EXEC816_COMPAT_GEMDOS_H',
        '#include <exec/types.h>']
    for name,value in ABI['constants'].items():
        header.append(f'#define GEMDOS_{name} {value}'+('UL' if value>32767 else ''))
    header+=['#define FSTAT GEMDOS_FSTAT','typedef struct xattr {']
    for name,kind,offset in ABI['xattr']['fields']:
        declaration=kind+' '+name if '[' not in kind else kind.split('[')[0]+' '+name+'['+kind.split('[')[1]
        header.append('    '+declaration+';')
    header+=['} XATTR;',*ABI['calls'],'#endif','']
    layout=['/* Generated by tools/generate_gemdos_compat.py; MIT. */',
        '#include <compat/gemdos.h>','#include <stddef.h>',
        '__attribute__((section("exec_layout")))','const UWORD ExecGemdosLayout[]={',
        '    sizeof(XATTR),']
    layout += ['    offsetof(XATTR,'+name+'),' for name,kind,offset in ABI['xattr']['fields']]
    layout += ['    sizeof(WORD),','    sizeof(LONG),','    sizeof(void *),','};','']
    return {ROOT/'c/include/compat/gemdos.h':'\n'.join(header),
        ROOT/'c/compat/gemdos/layout.c':'\n'.join(layout)}


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    for path,content in files().items():
        if args.check:
            if not path.exists() or path.read_text()!=content:
                raise SystemExit('Stale GEMDOS source interface: '+str(path))
        else:
            path.parent.mkdir(parents=True,exist_ok=True)
            path.write_text(content)
